// Transform Airtable records to our API format
const airtableRecords = $input.first().json.records || [];

const records = airtableRecords.map(record => ({
  airtable_id: record.id,
  rule_name: record.fields['Rule Name'] || '',
  category: (record.fields['Category'] || 'general').toLowerCase(),
  instruction: record.fields['Instruction'] || '',
  priority: record.fields['Priority'] || 50,
  active: record.fields['Active'] !== false
})).filter(r => r.rule_name && r.instruction);

return [{ json: { records } }];

